#include <hip/hip_runtime.h>
extern "C" __global__ void probe_signed16(const short2* a,const short2* b,int* output) {
    const unsigned i=blockIdx.x*blockDim.x+threadIdx.x;
    output[i]=amd_mixed_dot(a[i],b[i],0,false);
}
extern "C" __global__ void probe_unsigned16(const ushort2* a,const ushort2* b,unsigned* output) {
    const unsigned i=blockIdx.x*blockDim.x+threadIdx.x;
    output[i]=amd_mixed_dot(a[i],b[i],0u,false);
}
extern "C" __global__ void probe_signed8(const char4* a,const char4* b,int* output) {
    const unsigned i=blockIdx.x*blockDim.x+threadIdx.x;
    output[i]=amd_mixed_dot(a[i],b[i],0,false);
}
extern "C" __global__ void probe_unsigned8(const uchar4* a,const uchar4* b,unsigned* output) {
    const unsigned i=blockIdx.x*blockDim.x+threadIdx.x;
    output[i]=amd_mixed_dot(a[i],b[i],0u,false);
}

